class Solution {
public:
    string mostCommonResponse(vector<vector<string>>& responses) {
        unordered_map<string, int> cnt;
        for (auto& day : responses) {
            unordered_set<string> s(day.begin(), day.end());
            for (auto& w : s) cnt[w]++;
        }
        string best;
        int bc = -1;
        for (auto& [w, c] : cnt)
            if (c > bc || (c == bc && w < best)) { bc = c; best = w; }
        return best;
    }
};

c.java:
class Solution {
    public String mostCommonResponse(List<List<String>> responses) {
        Map<String, Integer> cnt = new HashMap<>();
        for (List<String> day : responses)
            new HashSet<>(day).forEach(w -> cnt.merge(w, 1, Integer::sum));
        String best = null;
        int bc = -1;
        for (Map.Entry<String, Integer> e : cnt.entrySet())
            if (e.getValue() > bc || (e.getValue() == bc && (best == null || e.getKey().compareTo(best) < 0))) {
                bc = e.getValue(); best = e.getKey();
            }
        return best;
    }
}

