var mostCommonResponse = function(responses) {
    const cnt = new Map();
    for (const day of responses)
        for (const w of new Set(day))
            cnt.set(w, (cnt.get(w) || 0) + 1);
    let best = '', bc = -1;
    for (const [w, c] of cnt)
        if (c > bc || (c === bc && w < best)) { bc = c; best = w; }
    return best;
};
